export function getProduct(id: string): Product | undefined {
  return products.find((p) => p.id === id);
}

export function findProductIdByName(name: string): string | null {
  const norm = name.trim().toLowerCase();
  const p = products.find((x) => x.name.toLowerCase() === norm);
  return p ? p.id : null;
}

export function productsByCategory(category: CategoryId): Product[] {
  return products.filter((p) => p.category === category);
}

export function specLabelsByCategory(category: CategoryId): string[] {
  const labels: string[] = [];
  for (const p of productsByCategory(category)) {
    for (const label of Object.keys(p.specs)) {
      if (!labels.includes(label)) labels.push(label);
    }
  }
  return labels;
}

export function buildDynamicComparison(a: Product, b: Product): SpecRow[] {
  const labels = Array.from(
    new Set([...Object.keys(a.specs), ...Object.keys(b.specs)]),
  );
  return labels.map((label) => ({
    label,
    a: a.specs[label] ?? "-",
    b: b.specs[label] ?? "-",
    scoreA: a.ratings[label],
    scoreB: b.ratings[label],
  }));
}

export function specVerdict(scoreA?: number, scoreB?: number): "A" | "B" | "Seri" {
  if (scoreA === undefined || scoreB === undefined) return "Seri";
  const diff = scoreA - scoreB;
  if (Math.abs(diff) <= 2) return "Seri";
  return diff > 0 ? "A" : "B";
}

export interface VerdictResult {
  pemenang: string;
  menang: number;
  seri: number;
  kalah: number;
  totalSpecs: number;
  message: string;
}

export function buildVerdict(
  nameA: string,
  nameB: string,
  specs: SpecRow[],
): VerdictResult {
  let menang = 0;
  let seri = 0;
  let kalah = 0;
  for (const s of specs) {
    const v = specVerdict(s.scoreA, s.scoreB);
    if (v === "A") menang++;
    else if (v === "B") kalah++;
    else seri++;
  }
  const total = specs.length;
  const pemenang = menang > kalah ? nameA : menang < kalah ? nameB : null;
  const message =
    total === 0
      ? "Tidak ada data spesifikasi untuk dibandingkan."
      : menang > kalah
        ? `${nameA} unggul di ${menang} dari ${total} spesifikasi (${seri} seri).`
        : menang < kalah
          ? `${nameB} unggul di ${kalah} dari ${total} spesifikasi (${seri} seri).`
          : `Seimbang: masing-masing ${menang} spesifikasi unggul dari ${total} (${seri} seri).`;

  return {
    pemenang: pemenang ?? "Seimbang",
    menang,
    seri,
    kalah,
    totalSpecs: total,
    message,
  };
}

export interface OverallVerdict {
  pemenang: string;
  gap: number;
  label: "Seimbang" | "Tipis" | "Jelas" | "Telak";
  message: string;
}

// Pemenang overall SELALU ikut skor total (ChoiceLens Score), bukan hitungan
// spek — agar tidak pernah kontradiksi dengan angka headline yang tampil.
// Hitungan menang/seri/kalah per spek tetap dipakai sebagai rincian pendukung.
export function overallVerdict(
  nameA: string,
  nameB: string,
  scoreA: number,
  scoreB: number,
): OverallVerdict {
  const gap = Math.abs(scoreA - scoreB);
  const label: OverallVerdict["label"] =
    gap === 0 ? "Seimbang" : gap <= 3 ? "Tipis" : gap <= 7 ? "Jelas" : "Telak";
  if (gap === 0) {
    return {
      pemenang: "Seimbang",
      gap,
      label,
      message: `Seimbang: skor total sama ${scoreA} vs ${scoreB}.`,
    };
  }
  const winner = scoreA > scoreB ? nameA : nameB;
  return {
    pemenang: winner,
    gap,
    label,
    message: `${winner} menang ${label.toLowerCase()}, skor ${scoreA} vs ${scoreB}.`,
  };
}

